-- SmartStudy Subject Content Seed Script
-- Adds syllabus-aligned course content summaries for all catalog subjects

USE SmartStudyDB;

GO

IF OBJECT_ID('tempdb..#CourseContentSeed') IS NOT NULL
  DROP TABLE #CourseContentSeed;

CREATE TABLE #CourseContentSeed (
  SubjectCode NVARCHAR(50) NOT NULL,
  ContentSummary NVARCHAR(MAX) NOT NULL
);


MERGE CourseContents AS target
USING (
  SELECT s.SubjectID, c.ContentSummary
  FROM #CourseContentSeed c
  JOIN Subjects s ON s.SubjectCode = c.SubjectCode
) AS source
ON target.SubjectID = source.SubjectID
WHEN MATCHED THEN
  UPDATE SET
    target.ContentSummary = source.ContentSummary,
    target.UpdatedAt = GETUTCDATE()
WHEN NOT MATCHED BY TARGET THEN
  INSERT (SubjectID, ContentSummary, UpdatedAt)
  VALUES (source.SubjectID, source.ContentSummary, GETUTCDATE());

SELECT 'Course content seed completed successfully!' AS [Status];
SELECT COUNT(*) AS TotalCourseContentRows FROM CourseContents;
SELECT COUNT(*) AS ExpectedSeedSubjects FROM #CourseContentSeed;

IF OBJECT_ID('tempdb..#CourseContentSeed') IS NOT NULL
  DROP TABLE #CourseContentSeed;
